# ruff: noqa: E501
from __future__ import annotations

from uuid import UUID

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

from newsintel.api.dependencies import AnalystAuth
from newsintel.api.ui import COMMON_JS, render_app_page
from newsintel.domain.access import Permission

router = APIRouter(tags=["entity-dashboard"])


@router.get("/entities", response_class=HTMLResponse)
async def entities_dashboard(auth: AnalystAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "analyst")
    can_manage = Permission.CLAIMS_VERIFY.value in auth.permissions
    resolution_link = '<a class="button secondary" href="/entities/resolution">Resolution queue</a>' if can_manage else ""
    body = f"""
<section class="page-head"><div><div class="eyebrow">Canonical identity</div><h1>People & organisations</h1><p class="lead">Find people, organisations and places mentioned in stored reports. Names are linked only through approved aliases, not guessed from similar spelling.</p></div><div class="toolbar">{resolution_link}<span id="entityStatus" class="muted small" aria-live="polite">Enter at least 2 characters</span></div></section>
<section class="panel flat stack">
  <div class="search-hero"><input id="entityQuery" type="search" placeholder="Search entity names or approved aliases…" autocomplete="off"/><button id="entitySearchBtn" type="button">Search</button></div>
  <div class="grid three"><label>Type<select id="entityType"><option value="">Any type</option><option value="person">Person</option><option value="organization">Organization</option><option value="company">Company</option><option value="government_body">Government body</option><option value="location">Location</option><option value="other">Other</option></select></label><label>Country code<input id="entityCountry" maxlength="8" placeholder="IN, US…"/></label><div class="filter-actions"><button id="entityApply" class="secondary" type="button">Apply</button></div></div>
  <div class="notice">Exact canonical names and approved aliases are indexed. Merged identities are excluded from active search. A search match does not itself prove that every textual mention belongs to the entity.</div>
</section>
<section style="margin-top:18px"><div class="section-head"><h2>Entities</h2><span id="entityCount" class="muted small"></span></div><div id="entityResults" class="article-list"><div class="empty">Search the canonical entity registry.</div></div></section>
"""
    css = r"""
.search-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px}.filter-actions{display:flex;align-items:end}.entity-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;padding:17px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}.entity-card h2{margin:4px 0 6px}.entity-side{text-align:right;min-width:110px}@media(max-width:760px){.search-hero,.entity-card{grid-template-columns:1fr}.entity-side{text-align:left}}
"""
    scripts = f"<script>{COMMON_JS}\n" + r"""
const q=document.getElementById('entityQuery'), box=document.getElementById('entityResults');
function entityUrl(){const p=new URLSearchParams({q:q.value.trim(),limit:'50'});const t=document.getElementById('entityType').value,c=document.getElementById('entityCountry').value.trim().toUpperCase();if(t)p.set('entity_type',t);if(c)p.set('country_code',c);return `/api/v1/entities/search?${p.toString()}`}
async function runEntitySearch(){const query=q.value.trim();if(query.length<2){box.innerHTML='<div class="empty">Enter at least 2 characters.</div>';return}document.getElementById('entityStatus').textContent='Searching entity registry…';try{const d=await niApi(entityUrl());document.getElementById('entityCount').textContent=`${d.result_count} matches`;document.getElementById('entityStatus').textContent='Entity search complete';box.innerHTML=d.results.length?d.results.map(x=>`<article class="entity-card"><div><div class="pill-row">${niPill(niTitle(x.entity_type),'neutral')}${x.country_code?niPill(x.country_code,'neutral'):''}</div><h2><a href="/entities/${x.id}/intelligence">${niEsc(x.canonical_name)}</a></h2>${x.matched_alias?`<div class="muted small">Matched alias: ${niEsc(x.matched_alias)}</div>`:''}<div class="muted small">${x.alias_count} approved aliases</div></div><div class="entity-side"><a class="button secondary" href="/entities/${x.id}/intelligence">Open profile</a></div></article>`).join(''):'<div class="empty">No active canonical entities matched.</div>'}catch(e){document.getElementById('entityStatus').textContent='Entity search unavailable';box.innerHTML=`<div class="error-box">${niEsc(e.message)}</div>`}}
document.getElementById('entitySearchBtn').onclick=runEntitySearch;document.getElementById('entityApply').onclick=runEntitySearch;q.addEventListener('keydown',e=>{if(e.key==='Enter')runEntitySearch()});q.addEventListener('input',niDebounce(runEntitySearch,350));
""" + "</script>"
    return render_app_page(title="Entity Intelligence", body=body, active="entities", role=role, scripts=scripts, extra_css=css)


@router.get("/entities/resolution", response_class=HTMLResponse)
async def entity_resolution_dashboard(auth: AnalystAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "analyst")
    can_manage = Permission.CLAIMS_VERIFY.value in auth.permissions
    hidden = "" if can_manage else "hidden"
    body = f"""
<section class="page-head"><div><div class="eyebrow">Human identity review</div><h1>Review matching names</h1><p class="lead">Review names that may refer to the same person or organisation. A reviewer must confirm any merge; similar spellings are not enough.</p></div><div class="toolbar"><a class="button secondary" href="/entities">Entity directory</a><button id="scanConflicts" type="button" {hidden}>Scan conflicts</button></div></section>
<section class="panel flat"><div class="toolbar"><label>Status<select id="candidateStatus"><option value="pending">Pending</option><option value="accepted">Accepted</option><option value="rejected">Rejected</option><option value="all">All</option></select></label><button id="reloadCandidates" class="secondary" type="button">Reload</button></div><div class="notice">A shared name or alias is only a review signal. Merge direction must be chosen explicitly, and incompatible entity types/country codes are rejected by the backend.</div></section>
<section style="margin-top:18px"><div class="section-head"><h2>Resolution candidates</h2><span id="candidateCount" class="muted small"></span></div><div id="candidateBox" class="article-list"><div class="skeleton" style="height:120px"></div></div></section>
<section class="panel flat" style="margin-top:18px"><div class="section-head"><h2>Recent resolution actions</h2></div><div id="actionBox" class="stack"><div class="skeleton" style="height:90px"></div></div></section>
<dialog id="mergeDialog"><form method="dialog" class="dialog-card"><div class="section-head"><h2>Merge canonical entities</h2><button class="ghost" value="cancel">Close</button></div><input id="mergeCandidate" type="hidden"/><label>Source entity<select id="mergeSource"></select></label><label>Target entity<select id="mergeTarget"></select></label><label>Rationale<textarea id="mergeRationale" maxlength="2000" placeholder="Explain why these records represent the same real-world entity."></textarea></label><div class="notice warn">The source record is preserved as merged for audit, while aliases, identifiers and exact mention links are consolidated into the target.</div><button id="confirmMerge" type="button">Confirm merge</button></form></dialog>
<dialog id="rejectDialog"><form method="dialog" class="dialog-card"><div class="section-head"><h2>Reject conflict candidate</h2><button class="ghost" value="cancel">Close</button></div><input id="rejectCandidate" type="hidden"/><label>Rationale<textarea id="rejectRationale" maxlength="2000" placeholder="Explain why these identities should remain separate."></textarea></label><button id="confirmReject" type="button">Reject candidate</button></form></dialog>
"""
    scripts = f"<script>{COMMON_JS}\nconst canManage={'true' if can_manage else 'false'};let candidates=[];\n" + r"""
function entityRows(c){return Array.isArray(c.evidence?.entities)?c.evidence.entities:[]}
function candidateCard(c){const rows=entityRows(c);const items=rows.map(e=>`<div class="resolution-entity"><div><b><a href="/entities/${niEsc(e.id)}/intelligence">${niEsc(e.canonical_name)}</a></b><div class="muted small">${niEsc(niTitle(e.entity_type))}${e.country_code?` · ${niEsc(e.country_code)}`:''}</div><div class="muted small">${(e.matches||[]).map(m=>`${niTitle(m.basis)}: “${niEsc(m.text)}”`).join(' · ')}</div></div></div>`).join('');const controls=canManage&&c.status==='pending'?`<div class="toolbar"><button class="secondary merge-candidate" data-id="${c.id}" type="button">Review merge</button><button class="ghost reject-candidate" data-id="${c.id}" type="button">Keep separate</button></div>`:'';return `<article class="story-card"><div><div class="pill-row">${niPill(niTitle(c.candidate_type),'warn')}${niPill(niTitle(c.status),c.status==='pending'?'warn':c.status==='accepted'?'good':'neutral')}</div><h2>Shared normalized identity: ${niEsc(c.normalized_value)}</h2><div class="resolution-grid">${items}</div>${controls}</div><div class="story-side">${niDate(c.created_at)}</div></article>`}
async function loadCandidates(){try{const status=document.getElementById('candidateStatus').value;candidates=await niApi(`/api/v1/entities/resolution/candidates?status=${encodeURIComponent(status)}&limit=200`);document.getElementById('candidateCount').textContent=`${candidates.length} shown`;document.getElementById('candidateBox').innerHTML=candidates.length?candidates.map(candidateCard).join(''):'<div class="empty">No candidates in this state.</div>';document.querySelectorAll('.merge-candidate').forEach(b=>b.onclick=()=>openMerge(b.dataset.id));document.querySelectorAll('.reject-candidate').forEach(b=>b.onclick=()=>{document.getElementById('rejectCandidate').value=b.dataset.id;document.getElementById('rejectRationale').value='';document.getElementById('rejectDialog').showModal()})}catch(e){document.getElementById('candidateBox').innerHTML=`<div class="error-box">${niEsc(e.message)}</div>`}}
async function loadActions(){try{const rows=await niApi('/api/v1/entities/resolution/actions?limit=50');document.getElementById('actionBox').innerHTML=rows.length?rows.map(a=>`<div class="evidence-item"><div class="pill-row">${niPill(niTitle(a.action_type),a.action_type==='merge'?'good':'neutral')}</div><b>${niEsc(a.rationale)}</b><div class="muted small">Source ${niEsc(a.source_entity_id)}${a.target_entity_id?` → target ${niEsc(a.target_entity_id)}`:''}${a.new_entity_id?` → new ${niEsc(a.new_entity_id)}`:''} · ${niDate(a.created_at)}</div></div>`).join(''):'<div class="empty">No entity-resolution actions recorded.</div>'}catch(e){document.getElementById('actionBox').innerHTML=`<div class="error-box">${niEsc(e.message)}</div>`}}
function openMerge(id){const c=candidates.find(x=>x.id===id);if(!c)return;const rows=entityRows(c);const options=rows.map(e=>`<option value="${niEsc(e.id)}">${niEsc(e.canonical_name)} · ${niEsc(niTitle(e.entity_type))}</option>`).join('');document.getElementById('mergeCandidate').value=id;document.getElementById('mergeSource').innerHTML=options;document.getElementById('mergeTarget').innerHTML=options;if(rows.length>1)document.getElementById('mergeTarget').selectedIndex=1;document.getElementById('mergeRationale').value='';document.getElementById('mergeDialog').showModal()}
if(canManage){document.getElementById('scanConflicts').onclick=async()=>{const b=document.getElementById('scanConflicts');b.disabled=true;try{const r=await niApi('/api/v1/entities/resolution/scan',{method:'POST'});niToast(`Detected ${r.detected_candidates} conflict groups; ${r.new_candidates} new candidates`,'good');await loadCandidates()}catch(e){niToast(e.message,'bad')}finally{b.disabled=false}};document.getElementById('confirmMerge').onclick=async()=>{const source=document.getElementById('mergeSource').value,target=document.getElementById('mergeTarget').value,rationale=document.getElementById('mergeRationale').value.trim();if(source===target){niToast('Choose different source and target entities','bad');return}try{await niApi('/api/v1/entities/resolution/merge',{method:'POST',body:JSON.stringify({source_entity_id:source,target_entity_id:target,candidate_id:document.getElementById('mergeCandidate').value,rationale})});document.getElementById('mergeDialog').close();niToast('Entities merged with audit trail','good');await Promise.all([loadCandidates(),loadActions()])}catch(e){niToast(e.message,'bad')}};document.getElementById('confirmReject').onclick=async()=>{try{await niApi(`/api/v1/entities/resolution/candidates/${document.getElementById('rejectCandidate').value}/reject`,{method:'POST',body:JSON.stringify({rationale:document.getElementById('rejectRationale').value.trim()})});document.getElementById('rejectDialog').close();niToast('Candidate kept separate','good');await Promise.all([loadCandidates(),loadActions()])}catch(e){niToast(e.message,'bad')}}}
document.getElementById('candidateStatus').onchange=loadCandidates;document.getElementById('reloadCandidates').onclick=()=>Promise.all([loadCandidates(),loadActions()]);Promise.all([loadCandidates(),loadActions()]);
""" + "</script>"
    css = ".resolution-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px;margin:12px 0}.resolution-entity{padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--surface-2)}"
    return render_app_page(title="Entity Resolution", body=body, active="entities", role=role, scripts=scripts, extra_css=css)


@router.get("/entities/{entity_id}/intelligence", response_class=HTMLResponse)
async def entity_profile_dashboard(entity_id: UUID, auth: AnalystAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "analyst")
    can_refresh = Permission.CLAIMS_VERIFY.value in auth.permissions
    body = f"""
<section class="page-head"><div><div class="eyebrow">Entity profile</div><h1 id="entityName">Loading entity…</h1><p id="entityMeta" class="lead">Canonical identity, approved aliases, external identifiers and conservatively linked mentions.</p></div><div class="toolbar"><a class="button secondary" href="/entities">Entity directory</a><a class="button ghost" href="/entities/resolution">Resolution queue</a><button id="refreshMentions" type="button" {'hidden' if not can_refresh else ''}>Refresh exact mentions</button></div></section>
<div id="resolutionBanner"></div>
<section class="grid four" id="entityMetrics"><div class="metric"><div class="label">Claims</div><div class="value" id="eClaims">—</div></div><div class="metric"><div class="label">Articles</div><div class="value" id="eArticles">—</div></div><div class="metric"><div class="label">Events</div><div class="value" id="eEvents">—</div></div><div class="metric"><div class="label">Publishers</div><div class="value" id="ePublishers">—</div></div></section>
<section class="grid two" style="margin-top:18px"><div class="panel flat"><div class="section-head"><h2>Canonical identity</h2></div><div id="identityBox" class="stack"></div></div><div class="panel flat"><div class="section-head"><h2>External identifiers</h2></div><div id="externalBox" class="stack"></div></div></section>
<section class="panel flat" style="margin-top:18px"><div class="section-head"><h2>Approved aliases</h2><span class="muted small">Aliases are identity inputs, not independent evidence.</span></div><div id="aliasBox" class="stack"></div></section>
<section style="margin-top:18px"><div class="section-head"><h2>Linked mentions</h2><span class="muted small">Exact normalized canonical/alias links only</span></div><div id="mentionBox" class="article-list"><div class="skeleton" style="height:120px"></div></div></section>
<dialog id="splitDialog"><form method="dialog" class="dialog-card"><div class="section-head"><h2>Split alias into new entity</h2><button class="ghost" value="cancel">Close</button></div><input id="splitAliasId" type="hidden"/><div class="notice">Only exact mention links using this alias will move automatically. This does not infer that other similar text belongs to the new entity.</div><label>Selected alias<input id="splitAliasText" readonly/></label><label>New canonical name<input id="splitCanonical" maxlength="300"/></label><label>Entity type<select id="splitType"><option value="person">Person</option><option value="organization">Organization</option><option value="company">Company</option><option value="government_body">Government body</option><option value="location">Location</option><option value="other">Other</option></select></label><label>Country code<input id="splitCountry" maxlength="8"/></label><label>Rationale<textarea id="splitRationale" maxlength="2000"></textarea></label><button id="confirmSplit" type="button">Create split entity</button></form></dialog>
"""
    scripts = f"<script>{COMMON_JS}\nconst entityId='{entity_id}',canRefresh={str(can_refresh).lower()};let profile=null;\n" + r"""
async function loadProfile(){try{const d=await niApi(`/api/v1/entities/${entityId}/profile?mention_limit=100`);profile=d;document.getElementById('entityName').textContent=d.canonical_name;document.getElementById('entityMeta').textContent=`${niTitle(d.entity_type)}${d.country_code?` · ${d.country_code}`:''} · canonical key ${d.entity_key}`;document.getElementById('eClaims').textContent=d.claim_count;document.getElementById('eArticles').textContent=d.article_count;document.getElementById('eEvents').textContent=d.event_count;document.getElementById('ePublishers').textContent=d.publisher_count;document.getElementById('identityBox').innerHTML=`<div><b>Canonical name</b><div>${niEsc(d.canonical_name)}</div></div><div><b>Normalized name</b><div class="muted">${niEsc(d.normalized_name)}</div></div><div><b>Type</b><div>${niEsc(niTitle(d.entity_type))}</div></div><div><b>Resolution state</b><div>${niEsc(niTitle(d.resolution_status||'active'))}</div></div>`;if(d.resolution_status==='merged')document.getElementById('refreshMentions').hidden=true;document.getElementById('resolutionBanner').innerHTML=d.resolution_status==='merged'&&d.merged_into_entity_id?`<div class="notice warn"><b>Merged identity.</b> This source record is preserved for audit and excluded from active search. <a href="/entities/${d.merged_into_entity_id}/intelligence">Open active target entity</a>.</div>`:'';const ext=[...Object.entries(d.external_ids||{}).map(([k,v])=>({namespace:k,external_id:v})),...(d.linked_external_ids||[])];document.getElementById('externalBox').innerHTML=ext.length?ext.map(x=>`<div class="evidence-item"><b>${niEsc(x.namespace)}</b><div>${niEsc(x.external_id)}</div>${x.canonical_url?`<a class="small" href="${niSafeUrl(x.canonical_url)}" target="_blank" rel="noopener">Canonical record</a>`:''}</div>`).join(''):'<div class="empty">No linked external identifiers.</div>';document.getElementById('aliasBox').innerHTML=(d.aliases||[]).length?d.aliases.map(a=>{const canonical=a.normalized_alias===d.normalized_name;const action=canRefresh&&d.resolution_status==='active'&&!canonical?`<button class="ghost split-alias" data-id="${a.id}" data-alias="${niEsc(a.alias)}" type="button">Split alias</button>`:'';return `<div class="alias-row"><div>${niPill(`${a.alias}${a.language?` · ${a.language}`:''}`,'neutral')}<div class="muted small">${niEsc(a.source)} · confidence ${Number(a.confidence).toFixed(2)}${canonical?' · canonical-name alias':''}</div></div>${action}</div>`}).join(''):'<div class="empty">No approved aliases.</div>';document.querySelectorAll('.split-alias').forEach(b=>b.onclick=()=>openSplit(b.dataset.id,b.dataset.alias));document.getElementById('mentionBox').innerHTML=(d.recent_mentions||[]).length?d.recent_mentions.map(m=>`<article class="story-card"><div><div class="pill-row">${niPill(niTitle(m.link_basis),'good')}${niPill(m.publisher,'neutral')}</div><h2><a href="/claims/${m.claim_id}/investigation">${niEsc(m.claim_text)}</a></h2><div class="muted small">Mention text: “${niEsc(m.mention_text)}” · <a href="/articles/${m.article_id}/intelligence">${niEsc(m.article_title)}</a> · <a href="/events/${m.event_id}/intelligence">${niEsc(m.event_title)}</a></div></div><div class="story-side">${m.published_at?niRelative(m.published_at):''}</div></article>`).join(''):'<div class="empty"><b>No linked mentions yet.</b><div class="small" style="margin-top:6px">A verifier can refresh exact canonical/approved-alias links. Absence here does not mean the entity is absent from the corpus.</div></div>'}catch(e){document.getElementById('mentionBox').innerHTML=`<div class="error-box">${niEsc(e.message)}</div>`}}
function openSplit(id,alias){document.getElementById('splitAliasId').value=id;document.getElementById('splitAliasText').value=alias;document.getElementById('splitCanonical').value=alias;document.getElementById('splitType').value=profile?.entity_type||'other';document.getElementById('splitCountry').value=profile?.country_code||'';document.getElementById('splitRationale').value='';document.getElementById('splitDialog').showModal()}
if(canRefresh){document.getElementById('refreshMentions').onclick=async()=>{const b=document.getElementById('refreshMentions');b.disabled=true;try{const r=await niApi(`/api/v1/entities/${entityId}/refresh-mentions`,{method:'POST'});niToast(`Linked ${r.linked_mentions} exact mentions across ${r.linked_claims} claims`,'good');await loadProfile()}catch(e){niToast(e.message,'bad')}finally{b.disabled=false}};document.getElementById('confirmSplit').onclick=async()=>{try{const r=await niApi(`/api/v1/entities/${entityId}/split-alias`,{method:'POST',body:JSON.stringify({alias_id:document.getElementById('splitAliasId').value,canonical_name:document.getElementById('splitCanonical').value.trim(),entity_type:document.getElementById('splitType').value,country_code:document.getElementById('splitCountry').value.trim()||null,rationale:document.getElementById('splitRationale').value.trim()})});document.getElementById('splitDialog').close();niToast('Alias split into a new canonical entity','good');location.href=`/entities/${r.new_entity_id}/intelligence`}catch(e){niToast(e.message,'bad')}}}
loadProfile();
""" + "</script>"
    css = ".alias-row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line)}.alias-row:last-child{border-bottom:0}"
    return render_app_page(title="Entity Profile", body=body, active="entities", role=role, scripts=scripts, extra_css=css)
